import fs from 'node:fs';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-head-separate-comparison',dir=stage+'/browser',start=json(dir+'/STARTED.json');assert.equal(start.pid,235228);assert.equal(start.base,'http://127.0.0.1:63415');
const cmd="$p=Get-CimInstance Win32_Process -Filter 'ProcessId=235228'; if($null -eq $p){throw 'Owned process missing before scoped stop'}; if($p.Name -ne 'node.exe' -or $p.CommandLine -ne '\"C:\\Program Files\\nodejs\\node.exe\" serve-head-separate-comparison-20261023.mjs' -or $p.ParentProcessId -ne 222084){throw 'Owned identity changed'}; $before=$p | Select-Object ProcessId,ParentProcessId,Name,CommandLine,CreationDate; Stop-Process -Id 235228 -ErrorAction Stop; if(Get-Process -Id 235228 -ErrorAction SilentlyContinue){throw 'Still running'}; $before | ConvertTo-Json -Compress";
const stopped=JSON.parse(execFileSync('powershell.exe',['-NoProfile','-NonInteractive','-Command',cmd],{encoding:'utf8',windowsHide:true}));assert(Math.abs(new Date(stopped.CreationDate).getTime()-new Date(start.at).getTime())<10000);
fs.writeFileSync(dir+'/TERMINAL.json',JSON.stringify({at:new Date().toISOString(),pid:start.pid,stopped,stdinCloseRequestFailed:true,reason:'exec session stdin was closed; exact observed owned process verified and stopped. No owner preview process touched.',gracefulRequestReceiptAvailable:false,ownedTabsClosed:['167','168','169'],ownedServerStopped:true,previewChanged:false},null,2)+'\n',{flag:'wx'});const p=json('CURRENT_CHECKPOINT.json');p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='head-separate-browser');const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);console.log(JSON.stringify({ownedServerStopped:true,pid:start.pid,normalPreviewChanged:false}));
